/**
 * Türkiye odaklı hazır ajanlar: e-ticaret iadesi ve kargo, klinik ve hastane, emlak, sigorta, eğitim, belediye
 * hizmetleri, bankacılık, kamu ve KOBİ işleri. Talimatlar ortak bir iskeletle yazılır (rol, çalışma adımları,
 * sınırlar); destek ajanlarına uygun hazır prosedürler (iade, kargo, randevu, adres, iptal) bağlanır.
 */
type T = {
  id: string; ad: string; kategori: SablonKategori; sektor: Sektor; kapak: string; simge: number; aciklama: string; rol: string;
  adimlar: string[]; sinir?: string; karsilama: string; baslangiclar: string[]; etiketler: string[];
  devir?: string; kisisel?: boolean; yasak?: string[]; prosedur?: string[]; araclar?: AjanSablon["araclar"]; gerekli?: string[]; tetik?: AjanSablon["tetik"];
};
const S = (n: number) => `/gercek/galeri/3d${(n % 12) + 1}.webp`;
const H = (x: string) => `/gercek/havuz/gorsel/${x}.webp`;
/** Türkiye listesinde her pazarda da sunulanlar (ajanKatalog TR_VE_GLOBAL ile aynı): dil sabit Türkçe değil. */
const GLOBAL_TR = new Set(["isletme-yoneticisi", "site-asistani"]);
const yap = (t: T): AjanSablon => ({
  id: t.id, ad: t.ad, kategori: t.kategori, sektor: t.sektor, kapak: t.kapak, simge: S(t.simge), aciklama: t.aciklama,
  araclar: t.araclar ?? {}, karsilama: t.karsilama, baslangiclar: t.baslangiclar, etiketler: t.etiketler,
  ...(t.gerekli ? { gerekli: t.gerekli } : {}), ...(t.tetik ? { tetik: t.tetik } : {}),
  ...(t.devir ? { devir: { acik: true, kurallar: t.devir } } : {}),
  ...(t.kisisel || t.yasak ? { koruma: { ...(t.kisisel ? { kisisel: true } : {}), ...(t.yasak ? { yasakKonular: t.yasak } : {}) } } : {}),
  ...(t.prosedur ? { prosedurler: t.prosedur.map((p) => hazirKopya(p)!).filter(Boolean) } : {}),
  talimat: `${t.rol}\n\nÇalışma biçimin:\n${t.adimlar.map((a, i) => `${i + 1}. ${a}`).join("\n")}\n${t.sinir ?? "Bilgi bölümünde olmayan fiyat, tarih ya da kural uydurma; emin değilsen ekibe aktar."} ${GLOBAL_TR.has(t.id) ? "Yanıtların kısa olsun; karşındaki kişi hangi dilde yazıyorsa o dilde yanıt ver." : "Yanıtların kısa ve Türkçe olsun."}`,
});

